"""
Напоминания и таймеры — уведомлениями на телефон, даже когда Atlas закрыт.

  • «Напомни завтра в 8:30 про SAT», «поставь таймер на 10 минут», «какие у меня напоминания»,
    «отмени напоминание про чай» — голосом на компьютере или с телефона.
  • Напоминания общие: через общую память их видят и компьютер, и облако. В срок облако присылает
    уведомление на телефон, а компьютер (если включён) говорит вслух. Поставленные одновременно на
    двух устройствах — не теряются (слияние по записям).
  • Телефон: шестерёнка → «Включить уведомления» → «Проверить». Во вкладке «Дела» — список напоминаний.
  • Облако живёт по твоему времени (ATLAS_TZ, по умолчанию Бишкек), а не по UTC: «сегодня», «через час».
  • Облако само не засыпает (заходит на свой адрес каждые 9 минут), иначе напоминание пришло бы с опозданием.
  • Google: испорченный или отозванный токен — на компьютере сразу окно входа, в облаке — понятный ответ.
    Токен в Render понимается, даже если при вставке потерялась скобка или попали кавычки.
  • Облако: больше нет ошибки «no such table: task_log».

    python apply_reminders.py
    python apply_reminders.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'.dockerignore': 'd164264b93bfe7ed834a15b30f7a26366ba0cdf63518834344b3c645e70268fb', '.gitignore': 'df10d4a8c10a059a8d55bd4b8cc7683b7271c0dfd510df7e8036d1410e03bfaf', 'brain/planner.py': 'c17c656896d1839c3f8a53a764041914e79a7a8f6f664c3261921f07b730b6af', 'brain/tools.py': '0e4919860a0c8b8b004b9e5dfc9a6a3389df8acb994feb44af034d39ffde57a4', 'cloud/atlas_cloud.py': 'd53672ef83a7d6fb463450dbc5ccf54b9b2fc03dd836e746cf906215bd6fe4cc', 'cloud/render/requirements.txt': '1f64d493f7999a1d5a25f330723d19d53d846cae99c01343ab746c8cccb75a1b', 'cloud/requirements.txt': '728329ddcccface349f962aabcd4cb599fe2e2ded3668377eac16c580588eb71', 'cloud/stubs.py': '34f5ffe011b5320637293e50735f2837389ab3ec5c8c597d94ccc1a68cb28ceb', 'core/cloud_sync.py': 'aba89b08936489fbc8af550b91b0c043e15ea74e5c6653f84c97fc301449f9a0', 'google_auth.py': 'b98b93006dc0bc0fbd9764f6a04b7f2a358642ec7b238d59468b536f01861c02', 'phone/panels.py': '29f3630b9d6ad1a07cd485845cd037a979f9d9122cb8a535d831bdd48e472bde', 'phone/static/index.html': '89e7b2301b5f8988e1f6eb1b043a7d8418e821ea55ae3fbf010d6a5464862991', 'phone/static/sw.js': '6c20ff456d263e2904ae6be97b9b809ac8d35254060f8b90df3d2c2954299357', 'reminders.py': '60d9f9eb1dab4077b04aeba30c9f6f22833fa8186da2c8fd46c93ab3f127a1bb', 'tests/test_cloud_brain.py': '09f914f3e7e6e1e7e5e81a0babbc14f25d7e86e1386bd1d95d02d3eed8d94d90', 'tool_router.py': '20d652c873ac9b13b3cf33e20f7dca9ee6ce22f2219a71a2a34dd91d1ec6cb68', 'core/push.py': None, 'core/webpush.py': None, 'tests/test_reminders.py': None}
NEW = {'.dockerignore': '', '.gitignore': '', 'brain/planner.py': '', 'brain/tools.py': '', 'cloud/atlas_cloud.py': '', 'cloud/render/requirements.txt': '', 'cloud/requirements.txt': '', 'cloud/stubs.py': '', 'core/cloud_sync.py': '', 'google_auth.py': '', 'phone/panels.py': '', 'phone/static/index.html': '', 'phone/static/sw.js': '', 'reminders.py': '', 'tests/test_cloud_brain.py': '', 'tool_router.py': '', 'core/push.py': '', 'core/webpush.py': '', 'tests/test_reminders.py': ''}
TAG = "backup_reminders_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        src = os.path.join(backup, *rel.split("/"))
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(src, p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if "def set_reminder" in open(p("reminders.py"), encoding="utf-8").read():
    sys.exit("Уже установлено. Проверка: python tests/test_reminders.py")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ напоминания и таймеры: общие для компьютера и облака, приходят уведомлением на телефон")
print("  ✓ телефон: «Включить уведомления» в настройках, список напоминаний во вкладке «Дела»")
print("  ✓ облако: твоё время вместо UTC, не засыпает; Google — понятные ответы; task_log")

try:
    import cryptography  # noqa: F401
except ImportError:
    print("  ! на компьютере нет библиотеки cryptography (нужна для тестов уведомлений): pip install cryptography")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push — Render обновится сам за 3–5 минут.")
